{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import org.joget.apps.app.service.AppUtil;
import org.joget.apps.app.service.AppService;
import org.joget.commons.util.LogUtil;
import org.joget.plugin.base.PluginManager;
import org.joget.plugin.base.ApplicationPlugin;
import java.sql.*;
import java.util.*;
import javax.sql.DataSource;

final String TAG = "SPLIT_NOTIFY";
final String MAIN_TABLE = "app_fd_portal_details_split";
final String PORTAL_URL = "https://joget2.excitel.in/jw/web/userview/split_portal/CHANGE_ME";
final String FALLBACK_EMAIL = "prakriti.singh@excitel.com";
final int DELAY_MS = 12000;
final int WINDOW_SECONDS = 120;

final String currentProcessId = workflowAssignment.getProcessId();
AppService appServiceMain = (AppService) AppUtil.getApplicationContext().getBean("appService");
String originId = appServiceMain.getOriginProcessId(currentProcessId);
final String recordId = (originId == null || originId.isEmpty()) ? currentProcessId : originId;

Thread backgroundEmailThread = new Thread(new Runnable() {
    public void run() {
        try {
            Thread.sleep(DELAY_MS);

            Connection con = null;
            String erpLegalName = "N/A";
            String erpPortalName = "N/A";
            String existingWindow = "N/A";
            String newPortalName = "N/A";
            String zone = "N/A";
            String startedBy = "N/A";
            String processStarted = "N/A";
            String ccEmail = "";
            List tasks = new ArrayList();

            try {
                DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
                con = ds.getConnection();

                PreparedStatement psMain = con.prepareStatement(
                    "SELECT c_erp_legal_name, c_erp_portal_name, c_existing_window_name, c_new_erp_portal_name, c_zone " +
                    "FROM " + MAIN_TABLE + " WHERE id IN (?, ?) OR c_parent_id = ? ORDER BY dateModified DESC LIMIT 1");
                psMain.setString(1, recordId);
                psMain.setString(2, currentProcessId);
                psMain.setString(3, currentProcessId);
                ResultSet rsMain = psMain.executeQuery();
                if (rsMain.next()) {
                    if (rsMain.getString(1) != null && !rsMain.getString(1).trim().isEmpty()) erpLegalName = rsMain.getString(1).trim();
                    if (rsMain.getString(2) != null && !rsMain.getString(2).trim().isEmpty()) erpPortalName = rsMain.getString(2).trim();
                    if (rsMain.getString(3) != null && !rsMain.getString(3).trim().isEmpty()) existingWindow = rsMain.getString(3).trim();
                    if (rsMain.getString(4) != null && !rsMain.getString(4).trim().isEmpty()) newPortalName = rsMain.getString(4).trim();
                    if (rsMain.getString(5) != null && !rsMain.getString(5).trim().isEmpty()) zone = rsMain.getString(5).trim();
                } else {
                    LogUtil.warn(TAG, "No record in " + MAIN_TABLE + " for: " + recordId + " / " + currentProcessId);
                }
                rsMain.close(); psMain.close();

                PreparedStatement ps = con.prepareStatement(
                    "SELECT act.Name, ass.ResourceId, proc.ResourceRequesterId, " +
                    "DATE_FORMAT(FROM_UNIXTIME(proc.Started / 1000), '%d %b %Y %h:%i %p'), " +
                    "DATE_FORMAT(FROM_UNIXTIME(act.Activated / 1000), '%d %b %Y %h:%i %p') " +
                    "FROM SHKProcesses proc " +
                    "JOIN SHKAssignmentsTable ass ON ass.ActivityProcessId = proc.Id " +
                    "JOIN SHKActivities act ON ass.Activity = act.oid " +
                    "WHERE proc.Id = ? AND act.State = 1000003 " +
                    "AND act.Activated >= (UNIX_TIMESTAMP() - ?) * 1000 " +
                    "ORDER BY act.Activated DESC");
                ps.setString(1, currentProcessId);
                ps.setInt(2, WINDOW_SECONDS + (DELAY_MS / 1000));
                ResultSet rs = ps.executeQuery();
                Set seen = new HashSet();
                while (rs.next()) {
                    String stage = rs.getString(1) != null ? rs.getString(1) : "N/A";
                    String user = rs.getString(2) != null ? rs.getString(2) : "";
                    if (rs.getString(3) != null) startedBy = rs.getString(3);
                    if (rs.getString(4) != null) processStarted = rs.getString(4);
                    String receivedAt = rs.getString(5) != null ? rs.getString(5) : "N/A";
                    if (user.isEmpty() || seen.contains(stage + "|" + user)) continue;
                    seen.add(stage + "|" + user);
                    tasks.add(new String[]{stage, user, receivedAt, ""});
                }
                rs.close(); ps.close();

                for (int i = 0; i < tasks.size(); i++) {
                    String[] t = (String[]) tasks.get(i);
                    PreparedStatement psEmail = con.prepareStatement("SELECT email FROM dir_user WHERE username = ?");
                    psEmail.setString(1, t[1]);
                    ResultSet rsEmail = psEmail.executeQuery();
                    if (rsEmail.next() && rsEmail.getString("email") != null) t[3] = rsEmail.getString("email").trim();
                    rsEmail.close(); psEmail.close();
                }

                if (!startedBy.equals("N/A")) {
                    PreparedStatement psCc = con.prepareStatement("SELECT email FROM dir_user WHERE username = ?");
                    psCc.setString(1, startedBy);
                    ResultSet rsCc = psCc.executeQuery();
                    if (rsCc.next() && rsCc.getString("email") != null) ccEmail = rsCc.getString("email").trim();
                    rsCc.close(); psCc.close();
                }
            } catch (Exception dbEx) {
                LogUtil.error(TAG, dbEx, "DB Error: " + currentProcessId);
            } finally {
                if (con != null) try { con.close(); } catch (Exception e) {}
            }

            if (tasks.isEmpty()) {
                LogUtil.warn(TAG, "No newly assigned open task found for: " + currentProcessId);
                return;
            }

            PluginManager pm = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
            ApplicationPlugin emailTool = (ApplicationPlugin) pm.getPlugin("org.joget.apps.app.lib.EmailTool");
            if (emailTool == null) {
                LogUtil.warn(TAG, "EmailTool plugin not found");
                return;
            }

            String th = "padding:12px;border:1px solid #dee2e6;background:#f8f9fa;font-weight:bold;width:35%;";
            String td = "padding:12px;border:1px solid #dee2e6;";

            for (int i = 0; i < tasks.size(); i++) {
                String[] t = (String[]) tasks.get(i);
                String activeStage = t[0];
                String pendingUser = t[1];
                String taskReceivedAt = t[2];
                String toEmail = (t[3] == null || t[3].isEmpty()) ? FALLBACK_EMAIL : t[3];
                String cc = ccEmail.equalsIgnoreCase(toEmail) ? "" : ccEmail;

                String subject = "⚠ Window Split: " + activeStage + " | " + erpLegalName;

                String body = "<html><body style='font-family:Arial,sans-serif;color:#333;margin:0;padding:0;'>"
                    + "<div style='background:linear-gradient(135deg,#1a1a2e,#16213e);padding:20px 30px;'>"
                    + "<h2 style='color:#fff;margin:0;font-size:18px;'>🪟 Window Split - Task Notification</h2>"
                    + "<p style='color:#adb5bd;margin:5px 0 0;font-size:13px;'>A task has been assigned and requires your action</p>"
                    + "</div>"
                    + "<div style='background:#fff3cd;border-left:5px solid #ffc107;padding:15px 20px;margin:0;'>"
                    + "<p style='margin:0;font-size:15px;font-weight:bold;color:#856404;'>⏳ Action Required: " + activeStage + "</p>"
                    + "<p style='margin:5px 0 0;font-size:13px;color:#856404;'>Please log in to the portal and complete this task at the earliest.</p>"
                    + "</div>"
                    + "<div style='padding:20px 30px;'>"
                    + "<p>Hi <strong>" + pendingUser + "</strong>,</p>"
                    + "<p>A new <strong>Window Split</strong> task has been assigned to you. Details are below:</p>"
                    + "<table style='border-collapse:collapse;width:100%;max-width:650px;border:1px solid #dee2e6;'>"
                    + "<tr style='background:#1a1a2e;'><th colspan='2' style='padding:12px;color:#fff;text-align:left;font-size:13px;'>📌 Task Details</th></tr>"
                    + "<tr><td style='" + th + "'>ERP Legal Name</td><td style='" + td + "font-weight:bold;color:#006eb7;'>" + erpLegalName + "</td></tr>"
                    + "<tr><td style='" + th + "'>ERP Portal Name</td><td style='" + td + "'>" + erpPortalName + "</td></tr>"
                    + "<tr><td style='" + th + "'>Existing Window Name</td><td style='" + td + "'>" + existingWindow + "</td></tr>"
                    + "<tr><td style='" + th + "'>New Portal Name</td><td style='" + td + "'>" + newPortalName + "</td></tr>"
                    + "<tr><td style='" + th + "'>Zone</td><td style='" + td + "'>" + zone + "</td></tr>"
                    + "<tr><td style='" + th + "'>Current Stage</td><td style='" + td + "'>"
                    + "<span style='background:#d4edda;color:#155724;padding:3px 10px;border-radius:10px;font-size:12px;font-weight:bold;'>" + activeStage + "</span></td></tr>"
                    + "<tr><td style='" + th + "'>Task Assigned To</td><td style='" + td + "font-weight:bold;'>" + pendingUser + "</td></tr>"
                    + "<tr><td style='" + th + "'>Process Initiated By</td><td style='" + td + "'>" + startedBy + "</td></tr>"
                    + "<tr><td style='" + th + "'>Process Started At</td><td style='" + td + "'>" + processStarted + "</td></tr>"
                    + "<tr><td style='" + th + "'>Task Received At</td><td style='" + td + "'>" + taskReceivedAt + "</td></tr>"
                    + "</table>"
                    + "<br><div style='text-align:center;margin:20px 0;'>"
                    + "<a href='" + PORTAL_URL + "' style='background:#006eb7;color:#fff;padding:12px 30px;border-radius:6px;text-decoration:none;font-weight:bold;font-size:14px;display:inline-block;'>🔗 Open Portal &amp; Complete Task</a>"
                    + "</div>"
                    + "<p style='color:#dc3545;font-weight:bold;font-size:13px;'>⚠ Please complete this task as soon as possible to avoid delays.</p>"
                    + "<hr style='border:none;border-top:1px solid #dee2e6;margin:20px 0;'>"
                    + "<p style='color:#aaa;font-size:11px;'>This is an automated notification from the Excitel Window Split System.</p>"
                    + "</div></body></html>";

                try {
                    Map props = new HashMap();
                    props.put("toSpecific", toEmail);
                    if (!cc.isEmpty()) props.put("cc", cc);
                    props.put("subject", subject);
                    props.put("message", body);
                    props.put("isHtml", "true");
                    emailTool.execute(props);
                    LogUtil.info(TAG, "Email sent for " + currentProcessId + " | stage=" + activeStage + " | user=" + pendingUser + " | to=" + toEmail + " | cc=" + cc);
                } catch (Exception mailEx) {
                    LogUtil.error(TAG, mailEx, "Email failed for " + currentProcessId + " | user=" + pendingUser);
                }
            }
        } catch (Exception ex) {
            LogUtil.error(TAG, ex, "Thread failed: " + ex.getMessage());
        }
    }
});

backgroundEmailThread.start();
LogUtil.info(TAG, "Main script done. User released. Process: " + currentProcessId);
"}}]}

