{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;

// ====================================================================
// CONFIG - Activity: remarksClearanceFinance
// Redo happens at: Resubmission From Create FCA Step
// Re-review target (what this resets): Create FCA
// ====================================================================
String TABLE_NAME = "app_fd_create_fca_split";
String DECISION_COLUMN = "c_decision";
String REMARKS_COLUMN = "c_finance_remarks";

Connection con = null;
try {
 // 1. Get the real Process ID from the workflow object
 String recordId = workflowAssignment.getProcessId();

 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();

 // 2. Reset BOTH the Decision flag AND the Remarks
 String sql = "UPDATE " + TABLE_NAME + " SET " + DECISION_COLUMN + " = 'no', " + REMARKS_COLUMN + " = '' WHERE c_parent_id = ? OR id = ?";

 PreparedStatement stmt = con.prepareStatement(sql);
 stmt.setString(1, recordId);
 stmt.setString(2, recordId);
 int rowsUpdated = stmt.executeUpdate();
 stmt.close();
 LogUtil.info("CLEANUP_TOOL", "Activity: remarksClearanceFinance | Table: " + TABLE_NAME + " | ID: " + recordId + " | Cleanup successful. Rows updated: " + rowsUpdated);
} catch (Exception e) {
 LogUtil.error("CLEANUP_TOOL", e, "Error during database cleanup for table " + TABLE_NAME + " (activity remarksClearanceFinance)");
} finally {
 if (con != null) {
 try { con.close(); } catch (SQLException e) { /* ignore */ }
 }
}"}}]}

