{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import org.joget.apps.app.service.AppUtil;
import org.joget.apps.app.service.AppService;
import org.joget.workflow.model.service.WorkflowManager;
import org.joget.commons.util.LogUtil;
import org.joget.plugin.base.PluginManager;
import org.joget.plugin.base.ApplicationPlugin;
import java.sql.*;
import java.util.*;
import java.text.SimpleDateFormat;
import javax.sql.DataSource;

String shiftTable = "app_fd_shiftTime_split";
String shiftDateField = "c_CHANGE_ME";
String erpTable = "app_fd_portal_details_split";
String mappingTable = "app_fd_zone_mapping";
String fixedEmails = "bd.helpdesk.del@excitel.com,psc_project@dl.excitel.in,hq.systems@excitel.com,noc.netmon@dl.excitel.in";

String processId = workflowAssignment.getProcessId();
AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
WorkflowManager wm = (WorkflowManager) AppUtil.getApplicationContext().getBean("workflowManager");
String recordId = appService.getOriginProcessId(processId);
if (recordId == null || recordId.isEmpty()) recordId = processId;

String rawDate = "";
String erpName = "N/A";
String existingWindow = "N/A";
String newErpName = "N/A";
String newPortalName = "N/A";
String zone = "";
List sdmUsers = new ArrayList();
List namUsers = new ArrayList();
Set roleEmails = new LinkedHashSet();

zone = wm.getProcessVariable(processId, "zone");
if (zone == null || zone.trim().isEmpty()) zone = wm.getProcessVariable(processId, "c_zone");
if (zone == null) zone = "";
zone = zone.trim();

Connection con = null;
try {
    DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
    con = ds.getConnection();

    PreparedStatement ps = con.prepareStatement("SELECT " + shiftDateField + " FROM " + shiftTable + " WHERE id = ?");
    ps.setString(1, processId);
    ResultSet rs = ps.executeQuery();
    if (rs.next() && rs.getString(1) != null) rawDate = rs.getString(1).trim();
    rs.close(); ps.close();

    PreparedStatement psErp = con.prepareStatement("SELECT c_erp_portal_name, c_zone, c_existing_window_name, c_new_portal_erp_legal_name, c_new_erp_portal_name FROM " + erpTable + " WHERE id IN (?, ?) OR c_parent_id = ? ORDER BY dateModified DESC LIMIT 1");
    psErp.setString(1, recordId);
    psErp.setString(2, processId);
    psErp.setString(3, processId);
    ResultSet rsErp = psErp.executeQuery();
    if (rsErp.next()) {
        if (rsErp.getString(1) != null && !rsErp.getString(1).trim().isEmpty()) erpName = rsErp.getString(1).trim();
        if (zone.isEmpty() && rsErp.getString(2) != null) zone = rsErp.getString(2).trim();
        if (rsErp.getString(3) != null && !rsErp.getString(3).trim().isEmpty()) existingWindow = rsErp.getString(3).trim();
        if (rsErp.getString(4) != null && !rsErp.getString(4).trim().isEmpty()) newErpName = rsErp.getString(4).trim();
        if (rsErp.getString(5) != null && !rsErp.getString(5).trim().isEmpty()) newPortalName = rsErp.getString(5).trim();
    } else {
        LogUtil.warn("SHIFT_SCHEDULE_MAIL", "No record in " + erpTable + " for: " + recordId + " / " + processId);
    }
    rsErp.close(); psErp.close();

    if (!zone.isEmpty()) {
        PreparedStatement psMap = con.prepareStatement("SELECT LOWER(c_role), c_username FROM " + mappingTable + " WHERE c_zone = ? AND LOWER(c_role) IN ('sdm', 'nam')");
        psMap.setString(1, zone);
        ResultSet rsMap = psMap.executeQuery();
        while (rsMap.next()) {
            String role = rsMap.getString(1);
            String uname = rsMap.getString(2);
            if (uname == null || uname.trim().isEmpty()) continue;
            uname = uname.trim();
            if ("sdm".equals(role) && !sdmUsers.contains(uname)) sdmUsers.add(uname);
            if ("nam".equals(role) && !namUsers.contains(uname)) namUsers.add(uname);
        }
        rsMap.close(); psMap.close();

        List allUsers = new ArrayList(sdmUsers);
        allUsers.addAll(namUsers);
        for (int i = 0; i < allUsers.size(); i++) {
            PreparedStatement psEmail = con.prepareStatement("SELECT email FROM dir_user WHERE username = ?");
            psEmail.setString(1, (String) allUsers.get(i));
            ResultSet rsEmail = psEmail.executeQuery();
            if (rsEmail.next()) {
                String e = rsEmail.getString("email");
                if (e != null && !e.trim().isEmpty()) roleEmails.add(e.trim());
                else LogUtil.warn("SHIFT_SCHEDULE_MAIL", "No email in dir_user for: " + allUsers.get(i));
            }
            rsEmail.close(); psEmail.close();
        }
    } else {
        LogUtil.warn("SHIFT_SCHEDULE_MAIL", "Zone is EMPTY - SDM/NAM not added for: " + processId);
    }
} catch (Exception dbEx) {
    LogUtil.error("SHIFT_SCHEDULE_MAIL", dbEx, "DB Error for: " + processId);
} finally {
    try { if (con != null) con.close(); } catch (Exception ce) {}
}

String shiftDate = rawDate.isEmpty() ? "N/A" : rawDate;
String[] formats = {"yyyy-MM-dd HH:mm:ss", "yyyy-MM-dd HH:mm", "MM/dd/yyyy HH:mm", "dd/MM/yyyy HH:mm", "dd-MM-yyyy HH:mm"};
for (int i = 0; i < formats.length && !rawDate.isEmpty(); i++) {
    try {
        SimpleDateFormat in = new SimpleDateFormat(formats[i]);
        in.setLenient(false);
        java.util.Date d = in.parse(rawDate);
        shiftDate = new SimpleDateFormat("dd MMM yyyy, hh:mm a").format(d);
        break;
    } catch (Exception pe) {}
}

Set allEmails = new LinkedHashSet();
String[] fixed = fixedEmails.split(",");
for (int i = 0; i < fixed.length; i++) {
    if (!fixed[i].trim().isEmpty()) allEmails.add(fixed[i].trim());
}
allEmails.addAll(roleEmails);

String toEmail = "";
for (Iterator it = allEmails.iterator(); it.hasNext();) {
    if (toEmail.length() > 0) toEmail += ",";
    toEmail += (String) it.next();
}

String td1 = "style='padding: 12px; border: 1px solid #ccc; background-color: #f9f9f9; font-weight: bold; width: 35%;'";
String td1b = "style='padding: 12px; border: 1px solid #ccc; font-weight: bold;'";
String td2 = "style='padding: 12px; border: 1px solid #ccc;'";

String subject = "Window Split User shifting schedule";
String body = "<html><body style='font-family: Arial, sans-serif; color: #333;'>"
    + "<p>Team,</p>"
    + "<p>User shifting is planned for <strong>" + shiftDate + "</strong> for Window split Case.</p>"
    + "<table style='border-collapse: collapse; width: 100%; max-width: 650px; border: 1px solid #ccc;'>"
    + "<tr><td " + td1 + ">ERP Name</td><td " + td2 + ">" + erpName + "</td></tr>"
    + "<tr><td " + td1b + ">Existing Window Name</td><td " + td2 + ">" + existingWindow + "</td></tr>"
    + "<tr><td " + td1 + ">New ERP Name</td><td " + td2 + ">" + newErpName + "</td></tr>"
    + "<tr><td " + td1b + ">New Portal Name</td><td " + td2 + ">" + newPortalName + "</td></tr>"
    + "<tr><td " + td1 + ">Zone</td><td " + td2 + ">" + (zone.isEmpty() ? "N/A" : zone) + "</td></tr>"
    + "<tr><td " + td1b + ">Shifting Date &amp; Time</td><td " + td2 + ">" + shiftDate + "</td></tr>"
    + "</table>"
    + "<br><p>This is a system-generated email.</p>"
    + "</body></html>";

try {
    PluginManager pm = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
    ApplicationPlugin emailTool = (ApplicationPlugin) pm.getPlugin("org.joget.apps.app.lib.EmailTool");
    if (emailTool != null) {
        Map props = new HashMap();
        props.put("toSpecific", toEmail);
        props.put("subject", subject);
        props.put("message", body);
        props.put("isHtml", "true");
        emailTool.execute(props);
        LogUtil.info("SHIFT_SCHEDULE_MAIL", "Sent for: " + processId + " | zone=" + zone + " | sdm=" + sdmUsers + " | nam=" + namUsers + " | date=" + rawDate + " | erp=" + erpName + " | to=" + toEmail);
    }
} catch (Exception ex) {
    LogUtil.error("SHIFT_SCHEDULE_MAIL", ex, "Email failed for: " + processId);
}
"}}]}

{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.commons.util.LogUtil;

// ====================================================================
// CONFIG - Activity: remarksClear
// Redo happens at: Resubmission Request by Legal
// Re-review target (what this resets): KYC Verification
// ====================================================================
String TABLE_NAME = "app_fd_kycVerify_split";
String DECISION_COLUMN = "c_decision";
String REMARKS_COLUMN = "c_legal_remarks";

Connection con = null;
try {
 // 1. Get the real Process ID from the workflow object
 String recordId = workflowAssignment.getProcessId();

 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();

 // 2. Reset BOTH the Decision flag AND the Remarks
 String sql = "UPDATE " + TABLE_NAME + " SET " + DECISION_COLUMN + " = 'no', " + REMARKS_COLUMN + " = '' WHERE c_parent_id = ? OR id = ?";

 PreparedStatement stmt = con.prepareStatement(sql);
 stmt.setString(1, recordId);
 stmt.setString(2, recordId);
 int rowsUpdated = stmt.executeUpdate();
 stmt.close();
 LogUtil.info("CLEANUP_TOOL", "Activity: remarksClear | Table: " + TABLE_NAME + " | ID: " + recordId + " | Cleanup successful. Rows updated: " + rowsUpdated);
} catch (Exception e) {
 LogUtil.error("CLEANUP_TOOL", e, "Error during database cleanup for table " + TABLE_NAME + " (activity remarksClear)");
} finally {
 if (con != null) {
 try { con.close(); } catch (SQLException e) { /* ignore */ }
 }
}"}}]}

