{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.app.service.AppService;
import org.joget.workflow.model.service.WorkflowManager;
import org.joget.commons.util.LogUtil;

String TAG = "SET_NAM_SDM_TOOL";
String FALLBACK = "admin";
String ZONE_TABLE = "app_fd_portal_details_split";
String MAP_TABLE = "app_fd_zone_mapping";

String processId = workflowAssignment.getProcessId();
WorkflowManager wm = (WorkflowManager) AppUtil.getApplicationContext().getBean("workflowManager");
AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
String recordId = appService.getOriginProcessId(processId);
if (recordId == null || recordId.isEmpty()) recordId = processId;

LogUtil.info(TAG, "========== START ==========");
LogUtil.info(TAG, "Process ID: " + processId + " | Record ID: " + recordId);

String zone = "";
String namUsername = "";
String sdmUsername = "";

zone = wm.getProcessVariable(processId, "zone");
LogUtil.info(TAG, "1. Workflow var 'zone': [" + zone + "]");
if (zone == null || zone.trim().isEmpty() || "null".equalsIgnoreCase(zone.trim())) zone = "";

if (zone.isEmpty()) {
 zone = wm.getProcessVariable(processId, "c_zone");
 LogUtil.info(TAG, "2. Workflow var 'c_zone': [" + zone + "]");
 if (zone == null || zone.trim().isEmpty() || "null".equalsIgnoreCase(zone.trim())) zone = "";
}

Connection con = null;
try {
 DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
 con = ds.getConnection();

 if (zone.isEmpty()) {
 PreparedStatement psZone = con.prepareStatement("SELECT c_zone FROM " + ZONE_TABLE + " WHERE id IN (?, ?) OR c_parent_id = ? ORDER BY dateModified DESC LIMIT 1");
 psZone.setString(1, recordId);
 psZone.setString(2, processId);
 psZone.setString(3, processId);
 ResultSet rsZone = psZone.executeQuery();
 if (rsZone.next()) {
 zone = rsZone.getString("c_zone");
 if (zone == null) zone = "";
 LogUtil.info(TAG, "3. Zone from DB: [" + zone + "]");
 } else {
 LogUtil.warn(TAG, "3. No record in " + ZONE_TABLE + " for: " + recordId + " / " + processId);
 }
 rsZone.close();
 psZone.close();
 }

 zone = zone.trim();
 LogUtil.info(TAG, "FINAL Zone value: [" + zone + "]");

 if (!zone.isEmpty()) {
 PreparedStatement psMap = con.prepareStatement("SELECT LOWER(TRIM(c_role)), c_username FROM " + MAP_TABLE + " WHERE LOWER(TRIM(c_zone)) = LOWER(?) AND LOWER(TRIM(c_role)) IN ('nam', 'sdm') ORDER BY dateModified DESC, dateCreated DESC");
 psMap.setString(1, zone);
 ResultSet rsMap = psMap.executeQuery();
 while (rsMap.next()) {
 String role = rsMap.getString(1);
 String uname = rsMap.getString(2);
 if (uname == null || uname.trim().isEmpty()) continue;
 if ("nam".equals(role) && namUsername.isEmpty()) namUsername = uname.trim();
 if ("sdm".equals(role) && sdmUsername.isEmpty()) sdmUsername = uname.trim();
 }
 rsMap.close();
 psMap.close();
 LogUtil.info(TAG, "4. NAM Found: [" + namUsername + "] | SDM Found: [" + sdmUsername + "]");
 } else {
 LogUtil.warn(TAG, "Zone is EMPTY - cannot find NAM/SDM!");
 }
} catch (Exception e) {
 LogUtil.error(TAG, e, "DB Error for: " + processId);
} finally {
 try { if (con != null) con.close(); } catch (Exception ex) {}
}

if (namUsername.isEmpty()) {
 namUsername = FALLBACK;
 LogUtil.warn(TAG, "5. NAM using fallback: " + namUsername);
}
if (sdmUsername.isEmpty()) {
 sdmUsername = FALLBACK;
 LogUtil.warn(TAG, "5. SDM using fallback: " + sdmUsername);
}

wm.processVariable(processId, "nam_username", namUsername);
wm.processVariable(processId, "sdm_username", sdmUsername);
LogUtil.info(TAG, "6. nam_username = " + namUsername + " | sdm_username = " + sdmUsername);
LogUtil.info(TAG, "========== END ==========");
"}}]}

