{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import org.joget.apps.app.service.AppUtil;
import org.joget.apps.app.service.AppService;
import org.joget.commons.util.LogUtil;
import org.joget.plugin.base.PluginManager;
import org.joget.plugin.base.ApplicationPlugin;
import java.sql.*;
import java.util.*;
import javax.sql.DataSource;

String activityDefId = "userShiftingDetailsNam";
String slaHours = "8";
String defaultEmail = "surjeet.rawat@dl.excitel.in";
String ccEmail = "";
String formTable = "";
String erpField = "c_erp_name";
String zoneField = "c_zone";

String processId = workflowAssignment.getProcessId();
AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
String recordId = appService.getOriginProcessId(processId);

String erpName = "N/A";
String zone = "N/A";
String startedBy = "N/A";
String activeStage = "N/A";
String processStarted = "N/A";
String taskReceivedAt = "N/A";
String pendingHours = "N/A";
List pendingUsers = new ArrayList();
Set emails = new LinkedHashSet();

Connection con = null;
try {
    DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
    con = ds.getConnection();

    String query = "SELECT act.Name, ass.ResourceId, proc.ResourceRequesterId, " +
        "DATE_FORMAT(FROM_UNIXTIME(proc.Started / 1000), '%Y-%m-%d %H:%i:%s'), " +
        "DATE_FORMAT(FROM_UNIXTIME(act.Activated / 1000), '%Y-%m-%d %H:%i:%s'), " +
        "ROUND((UNIX_TIMESTAMP() * 1000 - act.Activated) / 3600000, 1) " +
        "FROM SHKProcesses proc " +
        "JOIN SHKAssignmentsTable ass ON ass.ActivityProcessId = proc.Id " +
        "JOIN SHKActivities act ON ass.Activity = act.oid " +
        "WHERE proc.Id = ? AND act.ActivityDefinitionId = ? " +
        "ORDER BY act.Activated DESC";

    PreparedStatement ps = con.prepareStatement(query);
    ps.setString(1, processId);
    ps.setString(2, activityDefId);
    ResultSet rs = ps.executeQuery();
    boolean first = true;
    while (rs.next()) {
        if (first) {
            if (rs.getString(1) != null) activeStage = rs.getString(1);
            if (rs.getString(3) != null) startedBy = rs.getString(3);
            if (rs.getString(4) != null) processStarted = rs.getString(4);
            if (rs.getString(5) != null) taskReceivedAt = rs.getString(5);
            if (rs.getString(6) != null) pendingHours = rs.getString(6);
            first = false;
        }
        String u = rs.getString(2);
        if (u != null && !u.isEmpty() && !pendingUsers.contains(u)) pendingUsers.add(u);
    }
    rs.close(); ps.close();

    for (int i = 0; i < pendingUsers.size(); i++) {
        PreparedStatement psEmail = con.prepareStatement("SELECT email FROM dir_user WHERE username = ?");
        psEmail.setString(1, (String) pendingUsers.get(i));
        ResultSet rsEmail = psEmail.executeQuery();
        if (rsEmail.next()) {
            String e = rsEmail.getString("email");
            if (e != null && !e.trim().isEmpty()) emails.add(e.trim());
        }
        rsEmail.close(); psEmail.close();
    }

    if (!formTable.isEmpty() && recordId != null) {
        PreparedStatement psForm = con.prepareStatement("SELECT " + erpField + ", " + zoneField + " FROM " + formTable + " WHERE id = ?");
        psForm.setString(1, recordId);
        ResultSet rsForm = psForm.executeQuery();
        if (rsForm.next()) {
            if (rsForm.getString(1) != null) erpName = rsForm.getString(1);
            if (rsForm.getString(2) != null) zone = rsForm.getString(2);
        }
        rsForm.close(); psForm.close();
    }
} catch (Exception dbEx) {
    LogUtil.error("SLA_Breach_NAM", dbEx, "DB Error for: " + processId);
} finally {
    try { if (con != null) con.close(); } catch (Exception ce) {}
}

String toEmail = "";
for (Iterator it = emails.iterator(); it.hasNext();) {
    if (toEmail.length() > 0) toEmail += ",";
    toEmail += (String) it.next();
}
if (toEmail.isEmpty()) toEmail = defaultEmail;

String pendingUser = "N/A";
if (!pendingUsers.isEmpty()) {
    pendingUser = "";
    for (int i = 0; i < pendingUsers.size(); i++) {
        if (i > 0) pendingUser += ", ";
        pendingUser += (String) pendingUsers.get(i);
    }
}

String td1 = "style='padding: 12px; border: 1px solid #ccc; background-color: #f9f9f9; font-weight: bold; width: 35%;'";
