    + "<tr><td " + td1 + ">Process Started</td><td " + td2 + ">" + processStarted + "</td></tr>"
    + "<tr><td " + td1b + ">Task Received At</td><td " + td2 + ">" + taskReceivedAt + "</td></tr>"
    + "<tr><td " + td1 + ">Pending For</td><td style='padding: 12px; border: 1px solid #ccc; color: #FF0000; font-weight: bold;'>" + pendingHours + " hrs</td></tr>"
    + "</table>"
    + "<br><p style='color: #FF0000; font-weight: bold; font-size: 16px;'>This task is overdue. Please log in to the portal and complete it immediately.</p>"
    + "</body></html>";

try {
    PluginManager pm = (PluginManager) AppUtil.getApplicationContext().getBean("pluginManager");
    ApplicationPlugin emailTool = (ApplicationPlugin) pm.getPlugin("org.joget.apps.app.lib.EmailTool");
    if (emailTool != null) {
        Map props = new HashMap();
        props.put("toSpecific", toEmail);
        if (!ccEmail.isEmpty()) props.put("cc", ccEmail);
        props.put("subject", subject);
        props.put("message", body);
        props.put("isHtml", "true");
        emailTool.execute(props);
        LogUtil.info("SLA_Breach_NAM", "SLA email sent to " + toEmail + " for: " + processId);
    }
} catch (Exception ex) {
    LogUtil.error("SLA_Breach_NAM", ex, "Email failed for: " + processId);
}
