                        "script": "import org.joget.apps.app.service.AppUtil;
import org.joget.apps.form.model.FormRow;
import org.joget.apps.form.model.FormRowSet;
import org.joget.workflow.util.WorkflowUtil;
import java.sql.*;
import javax.sql.DataSource;
import org.joget.commons.util.LogUtil;

// 1. CACHE SAFETY GATE
FormRowSet cachedRows = (FormRowSet) WorkflowUtil.getHttpServletRequest().getAttribute("MASTER_DATA_CACHE");
if (cachedRows != null) { return cachedRows; }

FormRowSet rowSet = new FormRowSet();
Connection con = null; PreparedStatement stmt = null; ResultSet rs = null;

String recordId = AppUtil.processHashVariable("#assignment.processId#", null, null, null);
if (recordId == null || recordId.isEmpty() || recordId.contains("#")) { recordId = primaryKey; }

if (recordId != null && !recordId.isEmpty()) {
    try {
        DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
        con = ds.getConnection();

        stmt = con.prepareStatement("SELECT * FROM vw_erp_onboarding_master WHERE process_id = ?");
        stmt.setString(1, recordId);
        rs = stmt.executeQuery();

        if (rs.next()) {
            FormRow row = new FormRow(); 
            row.setId(recordId);

            // ==========================================================
            // 2. REWORK ALERT LOGIC (Finance / CNT / Budget)
            // ==========================================================
            String panDecision = rs.getString("pan_decision");
            String cntDecision = rs.getString("cnt_decision"); // Decision from Budget Feasibility table
            String budDecision = rs.getString("budget_decision"); // Alias from Budget Approval table

            String finRemarks = rs.getString("c_finance_remarks");
            String cntRemarks = rs.getString("c_cnt_remarks");
            String circleRemarks = rs.getString("c_circle_pnl_remarks");

            if ("yes".equalsIgnoreCase(panDecision) || "yes".equalsIgnoreCase(cntDecision) || "yes".equalsIgnoreCase(budDecision)) {

                StringBuilder alert = new StringBuilder();
                alert.append("<div style=\"background:#fff5f5; border:2px solid #fc8181; padding:20px; border-radius:10px; margin-bottom:25px; font-family:Arial;\">");
                alert.append("<h3 style=\"margin:0; color:#c53030;\">⚠️ ACTION REQUIRED: Corrections Needed</h3>");

                if ("yes".equalsIgnoreCase(panDecision)) {
                    alert.append("<p style=\"margin:10px 0 5px 0; color:#2d3748;\"><b>Finance Feedback:</b></p>");
                    alert.append("<div style=\"background:#fff; padding:10px; border:1px solid #feb2b2; border-radius:5px; font-style:italic; color:#742a2a; margin-bottom:10px;\">")
                         .append(finRemarks != null ? finRemarks : "Review required.").append("</div>");
                }

                if ("yes".equalsIgnoreCase(cntDecision)) {
                    alert.append("<p style=\"margin:10px 0 5px 0; color:#2d3748;\"><b>CNT Team Feedback:</b></p>");
                    alert.append("<div style=\"background:#fff; padding:10px; border:1px solid #feb2b2; border-radius:5px; font-style:italic; color:#742a2a; margin-bottom:10px;\">")
                         .append(cntRemarks != null ? cntRemarks : "Review required.").append("</div>");
                }

                if ("yes".equalsIgnoreCase(budDecision)) {
                    alert.append("<p style=\"margin:10px 0 5px 0; color:#2d3748;\"><b>Circle Budget Feedback:</b></p>");
                    alert.append("<div style=\"background:#fff; padding:10px; border:1px solid #feb2b2; border-radius:5px; font-style:italic; color:#742a2a;\">")
                         .append(circleRemarks != null ? circleRemarks : "Review required.").append("</div>");
                }

                alert.append("</div>");
                row.setProperty("rework_alert_html", alert.toString());
            }

            // ====================================================================
            // 3. RE-POPULATE EDITABLE FIELDS: CONFIRM FEASIBILITY (Step 3)
            // ====================================================================
            row.setProperty("connect_erp_on_fiber_p2p", rs.getString("c_connect_erp_on_fiber_p2p") != null ? rs.getString("c_connect_erp_on_fiber_p2p") : "");

            // Grids (JSON strings are mapped automatically by Joget)
            row.setProperty("tentative_fiber_budget", rs.getString("c_tentative_fiber_budget") != null ? rs.getString("c_tentative_fiber_budget") : "");
            row.setProperty("tentative_p2p_budget", rs.getString("c_tentative_p2p_budget") != null ? rs.getString("c_tentative_p2p_budget") : "");
            row.setProperty("tentative_equipment_budget", rs.getString("c_tentative_equipment_budget") != null ? rs.getString("c_tentative_equipment_budget") : "");
            row.setProperty("fiber_links_building_details", rs.getString("c_fiber_links_building_details") != null ? rs.getString("c_fiber_links_building_details") : "");
            row.setProperty("p2p_links_building_details", rs.getString("c_p2p_links_building_details") != null ? rs.getString("c_p2p_links_building_details") : "");
            row.setProperty("final_fiber_budget", rs.getString("c_final_fiber_budget") != null ? rs.getString("c_final_fiber_budget") : "");
            row.setProperty("final_equipment_budget", rs.getString("c_final_equipment_budget") != null ? rs.getString("c_final_equipment_budget") : "");

            // Current Remarks
            row.setProperty("cnt_remarks", rs.getString("c_cnt_remarks") != null ? rs.getString("c_cnt_remarks") : "");

            rowSet.add(row);

            // 4. SAVE TO CACHE
            WorkflowUtil.getHttpServletRequest().setAttribute("MASTER_DATA_CACHE", rowSet);
            LogUtil.info("FEASIBILITY_LOAD", "Data repopulated for ID: " + recordId);
        }
    } catch (Exception e) {
        LogUtil.error("MASTER_LOAD_ERROR", e, "Error in Feasibility Script: " + e.getMessage());
    } finally {
        try { if (rs != null) rs.close(); if (stmt != null) stmt.close(); if (con != null) con.close(); } catch (Exception x) {}
    }
}
return rowSet;",
