<div id="rework_display_zone"></div>

<script>
$(document).ready(function() {
    var retryCount = 0;

    function paintAlert() {
        // Find the hidden field (Joget sometimes adds prefixes, so we use $= to mean 'ends with')
        var alertField = $("[id$='rework_alert_html'], [name*='rework_alert_html']").first();
        var reworkCode = alertField.val();

        console.log("Checking for rework data... Attempt: " + retryCount);

        if (reworkCode && reworkCode.length > 20) {
            // Data found! Paint it.
            $("#rework_display_zone").html(reworkCode);

            // Hide the raw hidden field wrapper so it doesn't take up blank space
            alertField.closest(".form-cell").hide(); 
            console.log("SUCCESS: Rework Box Painted!");

        } else if (retryCount < 10) {
            // If data is empty, wait 500ms and try again (up to 5 seconds total)
            retryCount++;
            setTimeout(paintAlert, 500);
        } else {
            console.log("FAIL: Could not find data in rework_alert_html after 5 seconds.");
        }
    }

    // Start the process
    paintAlert();
});
</script>"
