            tl.append("<div id=\"card17\" style=\"display:none\">");
            tl.append(section("Team Assignment"));
            tl.append(row("Surge Team Assigned", surgeTeam17));
            tl.append(row("FSE Employee Codes", rs.getString("c_fse_employee_codes")));
            tl.append(section("FSE Verification"));
            tl.append(row("FSE Enrolled in HRMS", rs.getString("c_fse_proper_enrolled_in_hrms")));
            tl.append(row("FSE Mapped in PMS", rs.getString("c_fse_mapped_in_pms")));
            tl.append(row("FSE ID Login Confirmed", rs.getString("c_fse_id_login_confirmed")));
            tl.append("</div></div></div>"); // card17 end

            // ============================================================
            // CARD 18: FEEDBACK (LAST CARD)
            // ============================================================
            String pstFeedback = rs.getString("c_feedback_of_pst_training");
            boolean feedbackDone = pstFeedback != null && !pstFeedback.isEmpty();
            if (pstFeedback == null || pstFeedback.isEmpty()) pstFeedback = "Pending";
            tl.append("<div class=\"tl-node " + (feedbackDone ? "done" : "pending") + "\">");
            tl.append("<div class=\"tl-card green\">");
            tl.append("<div class=\"tl-card-header\" onclick=\"toggleCard('card18')\"><span>18. Feedback</span><span>" + badge(pstFeedback) + " &nbsp;<span id=\"card18_arrow\">▼</span></span></div>");
            tl.append("<div id=\"card18\" style=\"display:none\">");
            tl.append(section("Training Feedback"));
            tl.append(row("Feedback of PST Training", pstFeedback));
            tl.append(row("Feedback of PNT Training", rs.getString("c_feedback_of_pnt_training")));
            tl.append(section("Retraining"));
            tl.append(row("Retraining Required", rs.getString("c_retraining_required")));
            tl.append(row("Topics for Retraining", rs.getString("c_topics_name_for_retraining")));
            tl.append("</div></div></div>"); // card18 end

            // END NODE
            tl.append("<div class=\"tl-node\"><span class=\"tl-end\">✓ COMPLETED</span></div>");
            tl.append("</div></div>"); // closes tl-line, tl-wrap

            row.setProperty("full_timeline_html", tl.toString());
            rowSet.add(row);
            WorkflowUtil.getHttpServletRequest().setAttribute("TIMELINE_CACHE", rowSet);
        }
    } catch (Exception e) {
        LogUtil.error("TIMELINE_FAIL", e, "Script failed: " + e.getMessage());
    } finally {
        try { if (rs != null) rs.close(); } catch (Exception e) {}
        try { if (stmt != null) stmt.close(); } catch (Exception e) {}
        try { if (con != null) con.close(); } catch (Exception e) {}
    }
}
return rowSet;",
