            tl.append(".tl-node.done::before{background:#28a745;box-shadow:0 0 0 2px #28a745;}");
            tl.append(".tl-node.pending::before{background:#ccc;box-shadow:0 0 0 2px #ccc;}");
            tl.append(".tl-node.start-node::before{width:16px;height:16px;left:-27px;top:12px;background:#333;box-shadow:0 0 0 3px #333;}");
            tl.append(".tl-card{background:#fff;border:1px solid #e0e0e0;border-radius:8px;padding:15px;margin-bottom:5px;box-shadow:0 2px 6px rgba(0,0,0,0.05);}");
            tl.append(".tl-card.blue{border-left:5px solid #006eb7;}");
            tl.append(".tl-card.green{border-left:5px solid #28a745;}");
            tl.append(".tl-card.orange{border-left:5px solid #fd7e14;}");
            tl.append(".tl-card.purple{border-left:5px solid #6f42c1;}");
            tl.append(".tl-card.grey{border-left:5px solid #aaa;}");
            tl.append(".tl-card-header{font-weight:bold;font-size:14px;color:#333;margin-bottom:10px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;}");
            tl.append(".tl-card-header:hover{color:#006eb7;}");
            tl.append(".tl-row{display:flex;font-size:12.5px;padding:4px 0;border-bottom:1px solid #f5f5f5;}");
            tl.append(".tl-lbl{width:38%;font-weight:bold;color:#888;padding-right:8px;}");
            tl.append(".tl-val{width:62%;color:#222;word-break:break-word;}");
            tl.append(".tl-section{font-size:11px;font-weight:bold;text-transform:uppercase;color:#006eb7;background:#f0f7ff;padding:4px 8px;border-radius:4px;margin:10px 0 6px 0;letter-spacing:0.5px;}");
            tl.append(".tl-parallel{position:relative;padding-left:25px;border-left:2px dashed #ddd;margin-left:5px;margin-bottom:5px;}");
            tl.append(".tl-parallel-label{font-size:11px;font-weight:bold;color:#888;text-transform:uppercase;margin-bottom:6px;letter-spacing:0.5px;}");
            tl.append(".badge{display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:bold;}");
            tl.append(".badge.green{background:#d4edda;color:#155724;}");
            tl.append(".badge.red{background:#f8d7da;color:#721c24;}");
            tl.append(".badge.orange{background:#fff3cd;color:#856404;}");
            tl.append(".badge.grey{background:#e9ecef;color:#6c757d;}");
            tl.append(".tl-start{background:#333;color:#fff;display:inline-block;padding:5px 18px;border-radius:20px;font-size:13px;font-weight:bold;margin-bottom:10px;}");
            tl.append(".tl-end{background:#28a745;color:#fff;display:inline-block;padding:5px 18px;border-radius:20px;font-size:13px;font-weight:bold;margin-top:5px;}");
            tl.append("</style>");

            // JS TOGGLE
            tl.append("<script>function toggleCard(id){var b=document.getElementById(id);var a=document.getElementById(id+'_arrow');if(b.style.display==='none'){b.style.display='block';a.innerHTML='▲';}else{b.style.display='none';a.innerHTML='▼';}}</script>");

            // TIMELINE
            tl.append("<div class=\"tl-wrap\"><div class=\"tl-line\">");

            // START
            tl.append("<div class=\"tl-node start-node\"><span class=\"tl-start\">● START</span></div>");

            // ============================================================
            // CARD 1: ERP DETAILS
            // ============================================================
            // Card 1: if record exists in DB, ERP Details is done
            String erpOwner = rs.getString("c_owner_name");
            boolean erpDone = erpOwner != null && !erpOwner.isEmpty();
            String erpStatus = erpDone ? "Submitted" : "Pending";
            tl.append("<div class=\"tl-node " + (erpDone ? "done" : "pending") + "\">");
            tl.append("<div class=\"tl-card blue\">");
            tl.append("<div class=\"tl-card-header\" onclick=\"toggleCard('card1')\"><span>1. ERP Details</span><span>" + badge(erpStatus) + " &nbsp;<span id=\"card1_arrow\">▼</span></span></div>");
            tl.append("<div id=\"card1\" style=\"display:none\">");

            tl.append(section("Identity"));
            tl.append(row("Legal Name", rs.getString("c_erp_legal_name")));
            tl.append(row("Portal Name", rs.getString("c_erp_portal_name")));
            tl.append(row("Owner Name", rs.getString("c_owner_name")));
