FormRowSet cachedRows = (FormRowSet) WorkflowUtil.getHttpServletRequest().getAttribute("SPLIT_TIMELINE_CACHE");
if (cachedRows != null) { return cachedRows; }

public String s(ResultSet r, String col) {
    try {
        String v = r.getString(col);
        return (v == null || v.trim().isEmpty()) ? null : v.trim();
    } catch (Exception e) { return null; }
}

public String esc(String v) {
    if (v == null) return "";
    return v.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
}

public String renderFileLinks(String fileNames, String recId, String tableName) {
    if (fileNames == null || fileNames.trim().isEmpty() || fileNames.equals("-")) return "<span style='color:#aaa;'>No file</span>";
    if (recId == null || recId.isEmpty()) return esc(fileNames);
    try {
        String baseUrl = "/app_formuploads/" + tableName + "/" + recId + "/";
        StringBuilder links = new StringBuilder();
        for (String file : fileNames.split(";")) {
            String fileName = file.trim();
            if (!fileName.isEmpty()) {
                String encodedFile = java.net.URLEncoder.encode(fileName, "UTF-8").replaceAll("\\+", "%20");
                links.append("<a href=\"").append(baseUrl).append(encodedFile).append("\" target=\"_blank\"")
                     .append(" style=\"display:inline-block; background:#e8f4fd; color:#006eb7; padding:3px 8px; border-radius:4px; font-size:11px; text-decoration:none; margin:2px;\">⬇️ ")
                     .append(esc(fileName)).append("</a>");
            }
        }
        return links.toString();
    } catch (Exception e) { return esc(fileNames); }
}

public String renderGrid(String jsonStr) {
    if (jsonStr == null || jsonStr.trim().isEmpty() || !jsonStr.trim().startsWith("[")) {
        return "<span style='color:#aaa; font-size:12px;'>No data</span>";
    }
    try {
        JSONArray array = new JSONArray(jsonStr);
        if (array.length() == 0) return "<span style='color:#aaa; font-size:12px;'>No data</span>";
        JSONObject first = array.getJSONObject(0);
        StringBuilder sb = new StringBuilder("<div style=\"overflow-x:auto;\"><table style=\"width:100%; border-collapse:collapse; font-size:12px; margin:5px 0 10px 0;\">");
        sb.append("<tr style=\"background:#f1f1f1;\">");
        for (String key : first.keySet()) {
            sb.append("<th style=\"padding:6px 8px; border:1px solid #ddd; text-align:left; font-size:11px; color:#555;\">").append(esc(key)).append("</th>");
        }
        sb.append("</tr>");
        for (int i = 0; i < array.length(); i++) {
            JSONObject obj = array.getJSONObject(i);
            sb.append("<tr style=\"background:").append(i % 2 == 0 ? "#fff" : "#fafafa").append(";\">");
            for (String key : first.keySet()) {
                sb.append("<td style=\"padding:6px 8px; border:1px solid #eee;\">").append(esc(obj.optString(key, "-"))).append("</td>");
            }
            sb.append("</tr>");
        }
        sb.append("</table></div>");
        return sb.toString();
    } catch (Exception e) { return esc(jsonStr); }
}

public String row(String label, String value) {
    if (value == null || value.trim().isEmpty() || value.equals("-")) return "";
    return "<div class=\"tl-row\"><div class=\"tl-lbl\">" + label + "</div><div class=\"tl-val\">" + esc(value) + "</div></div>";
}

public String rawRow(String label, String html) {
    return "<div class=\"tl-row\"><div class=\"tl-lbl\">" + label + "</div><div class=\"tl-val\">" + html + "</div></div>";
}

public String section(String title) {
    return "<div class=\"tl-section\">" + title + "</div>";
}

public String remarks(String label, String value) {
    if (value == null || value.trim().isEmpty()) return "";
    return "<div class=\"remarks-box\"><b>" + label + ":</b> " + esc(value) + "</div>";
}

public String badge(String value) {
    if (value == null || value.trim().isEmpty()) return "<span class=\"badge grey\">PENDING</span>";
    String v = value.toLowerCase().trim();
    String color = "grey";
    if (v.equals("yes") || v.equals("approved") || v.equals("approve") || v.equals("completed") || v.equals("done") || v.equals("true") || v.equals("submitted") || v.equals("lock")) color = "green";
    else if (v.equals("no") || v.equals("rejected") || v.equals("reject") || v.equals("unlock")) color = "red";
    else if (v.equals("pending") || v.equals("in progress") || v.equals("na")) color = "orange";
    return "<span class=\"badge " + color + "\">" + esc(value.toUpperCase()) + "</span>";
}

public boolean isDone(ResultSet r, String pre) {
    return s(r, pre + "_done_at") != null;
}

public String stepBadge(ResultSet r, String pre, String primaryCol) {
    String v = (primaryCol == null) ? null : s(r, primaryCol);
    if (v != null) return v;
    return isDone(r, pre) ? "Done" : "Pending";
}

public void cardOpen(StringBuilder tl, String id, String title, String color, String badgeVal, boolean done, int level) {
    String lvl = level >= 2 ? "substep2 " : (level == 1 ? "substep " : "");
    tl.append("<div class=\"tl-node " + lvl + (done ? "done" : "pending") + "\">");
    tl.append("<div class=\"tl-card " + color + "\">");
    tl.append("<div class=\"tl-card-header\" onclick=\"toggleCard('" + id + "')\"><span>" + title + "</span><span>" + badge(badgeVal) + " &nbsp;<span id=\"" + id + "_arrow\">▼</span></span></div>");
    tl.append("<div id=\"" + id + "\" style=\"display:none\">");
}

public void cardClose(StringBuilder tl, ResultSet r, String pre) {
    if (pre != null && isDone(r, pre)) {
        tl.append(section("Completion"));
        tl.append(row("Completed By", s(r, pre + "_done_by")));
        tl.append(row("Completed On", s(r, pre + "_done_at")));
    }
    tl.append("</div></div></div>");
}

public void stepCard(StringBuilder tl, ResultSet r, String id, String title, String color, String pre, String primaryCol, int level) {
    cardOpen(tl, id, title, color, stepBadge(r, pre, primaryCol), isDone(r, pre), level);
}

