import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.workflow.util.WorkflowUtil;
import org.joget.commons.util.LogUtil;
import java.util.UUID;

Object request = WorkflowUtil.getHttpServletRequest();
String decision = (request != null) ? request.getParameter("decision") : ""; 
String remarksText = (request != null) ? request.getParameter("finance_remarks") : ""; 
String processId = AppUtil.processHashVariable("#assignment.processId#", null, null, null);
String userFullName = WorkflowUtil.getCurrentUserFullName();
String username = WorkflowUtil.getCurrentUsername();

LogUtil.info("DX9_FINAL_DEBUG", "--------------------------------------");
LogUtil.info("DX9_FINAL_DEBUG", "Process ID: " + processId);
LogUtil.info("DX9_FINAL_DEBUG", "Captured Decision: [" + decision + "]"); 
LogUtil.info("DX9_FINAL_DEBUG", "Captured Remarks: [" + remarksText + "]");

if ("yes".equalsIgnoreCase(decision)) {
    LogUtil.info("DX9_FINAL_DEBUG", "Decision is 'yes'. Inserting into app_fd_erp_process_history...");

    Connection con = null;
    try {
        DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
        con = ds.getConnection();
        String sql = "INSERT INTO app_fd_erp_process_history " +
                     "(id, c_parent_id, c_department, c_remarks, c_users, dateCreated, dateModified, createdBy, createdByName) " +
                     "VALUES (?, ?, ?, ?, ?, NOW(), NOW(), ?, ?)";

        PreparedStatement stmt = con.prepareStatement(sql);
        stmt.setString(1, UUID.randomUUID().toString());
        stmt.setString(2, processId);
        stmt.setString(3, "Finance");
        stmt.setString(4, remarksText);
        stmt.setString(5, userFullName);
        stmt.setString(6, username);
        stmt.setString(7, userFullName); 

        int rows = stmt.executeUpdate();
        LogUtil.info("DX9_FINAL_DEBUG", "DB SUCCESS: " + rows + " row(s) inserted.");

    } catch (Exception e) {
        LogUtil.error("DX9_FINAL_DEBUG", e, "SQL Error! Check if table app_fd_erp_process_history exists.");
    } finally {
        if (con != null) con.close();
    }
} else {
    LogUtil.info("DX9_FINAL_DEBUG", "SKIP: Decision was '" + decision + "', not 'yes'.");
}
LogUtil.info("DX9_FINAL_DEBUG", "--------------------------------------");"}
