            tl.append(row("Feedback of PST Training", pstFeedback));
            tl.append(row("Feedback of PNT Training", rs.getString("c_feedback_of_pnt_training")));
            tl.append(section("Retraining"));
            tl.append(row("Retraining Required", rs.getString("c_retraining_required")));
            tl.append(row("Topics for Retraining", rs.getString("c_topics_name_for_retraining")));
            tl.append("</div></div></div>"); // card18 end

            // END NODE
            tl.append("<div class=\"tl-node\"><span class=\"tl-end\">✓ COMPLETED</span></div>");
            tl.append("</div></div>"); // closes tl-line, tl-wrap

            row.setProperty("full_timeline_html", tl.toString());
            rowSet.add(row);
            WorkflowUtil.getHttpServletRequest().setAttribute("TIMELINE_CACHE", rowSet);
        }
    } catch (Exception e) {
        LogUtil.error("TIMELINE_FAIL", e, "Script failed: " + e.getMessage());
    } finally {
        try { if (rs != null) rs.close(); } catch (Exception e) {}
        try { if (stmt != null) stmt.close(); } catch (Exception e) {}
        try { if (con != null) con.close(); } catch (Exception e) {}
    }
}
return rowSet;",
