import org.json.JSONArray;
import org.json.JSONObject;

// ====================================================================
// 1. SAFETY GATE (CACHE)
// ====================================================================
FormRowSet cachedRows = (FormRowSet) WorkflowUtil.getHttpServletRequest().getAttribute("TIMELINE_CACHE");
if (cachedRows != null) { return cachedRows; }

// ====================================================================
// 2. FILE LINK HELPER
// ====================================================================
public String renderFileLinks(String fileNames, String recordId, String formId) {
    if (fileNames == null || fileNames.trim().isEmpty() || fileNames.equals("-")) return "<span style='color:#aaa;'>No file</span>";
    try {
        String baseUrl = "/app_formuploads/" + formId + "/" + recordId + "/";
        LogUtil.info("FILE_DEBUG", "URL: [" + baseUrl + "] | Files: [" + fileNames + "]");
        StringBuilder links = new StringBuilder();
        for (String file : fileNames.split(";")) {
            String fileName = file.trim();
            if (!fileName.isEmpty()) {
                String encodedFile = java.net.URLEncoder.encode(fileName, "UTF-8").replaceAll("\\+", "%20");
                links.append("<a href=\"").append(baseUrl).append(encodedFile)
                     .append("\" target=\"_blank\"")
                     .append(" style=\"display:inline-block; background:#e8f4fd; color:#006eb7; padding:3px 8px; border-radius:4px; font-size:11px; text-decoration:none; margin:2px;\">⬇️ ")
                     .append(fileName).append("</a>");
            }
        }
        return links.toString();
    } catch (Exception e) { return fileNames; }
}

// ====================================================================
// 3. GRID RENDERER HELPER
// ====================================================================
public String renderGrid(String jsonStr) {
    if (jsonStr == null || jsonStr.trim().isEmpty() || !jsonStr.trim().startsWith("[")) {
        return "<span style='color:#aaa; font-size:12px;'>No data</span>";
    }
    try {
        JSONArray array = new JSONArray(jsonStr);
        if (array.length() == 0) return "<span style='color:#aaa; font-size:12px;'>No data</span>";
        JSONObject first = array.getJSONObject(0);
        StringBuilder sb = new StringBuilder("<table style=\"width:100%; border-collapse:collapse; font-size:12px; margin:5px 0 10px 0;\">");
        sb.append("<tr style=\"background:#f1f1f1;\">");
        for (String key : first.keySet()) {
            sb.append("<th style=\"padding:6px 8px; border:1px solid #ddd; text-align:left; font-size:11px; color:#555;\">").append(key).append("</th>");
        }
        sb.append("</tr>");
        for (int i = 0; i < array.length(); i++) {
            JSONObject obj = array.getJSONObject(i);
            sb.append("<tr style=\"background:").append(i % 2 == 0 ? "#fff" : "#fafafa").append(";\">");
            for (String key : first.keySet()) {
                sb.append("<td style=\"padding:6px 8px; border:1px solid #eee;\">").append(obj.optString(key, "-")).append("</td>");
            }
            sb.append("</tr>");
        }
        sb.append("</table>");
        return sb.toString();
    } catch (Exception e) { return jsonStr; }
}

// ====================================================================
// 4. ROW HELPER
// ====================================================================
public String row(String label, String value) {
    if (value == null || value.trim().isEmpty() || value.equals("-")) return "";
    return "<div class=\"tl-row\"><div class=\"tl-lbl\">" + label + "</div><div class=\"tl-val\">" + value + "</div></div>";
}

// ====================================================================
// 5. SECTION HEADER HELPER
// ====================================================================
public String section(String title) {
    return "<div class=\"tl-section\">" + title + "</div>";
}

// ====================================================================
// 6. STATUS BADGE HELPER
// ====================================================================
public String badge(String value) {
    if (value == null || value.trim().isEmpty()) return "<span class=\"badge grey\">Pending</span>";
    String v = value.toLowerCase().trim();
    String color = "grey";
    if (v.equals("yes") || v.equals("approved") || v.equals("approve") || v.equals("completed") || v.equals("done")) color = "green";
    else if (v.equals("no") || v.equals("rejected") || v.equals("reject")) color = "red";
    else if (v.equals("pending") || v.equals("in progress")) color = "orange";
    return "<span class=\"badge " + color + "\">" + value.toUpperCase() + "</span>";
}

// ====================================================================
// 7. MAIN
// ====================================================================
FormRowSet rowSet = new FormRowSet();
Connection con = null; PreparedStatement stmt = null; ResultSet rs = null;

String processId = AppUtil.processHashVariable("#assignment.processId#", null, null, null);
String recordId = (processId != null && !processId.isEmpty() && !processId.contains("#")) ? processId : primaryKey;
LogUtil.info("TIMELINE_DEBUG", "recordId: [" + recordId + "]");

if (recordId != null && !recordId.isEmpty()) {
    try {
        DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
        con = ds.getConnection();
        stmt = con.prepareStatement("SELECT * FROM vw_erp_onboarding_master WHERE process_id = ?");
        stmt.setString(1, recordId);
        rs = stmt.executeQuery();

        if (rs.next()) {
            FormRow row = new FormRow();
            row.setId(recordId);
            StringBuilder tl = new StringBuilder();

            // ============================================================
            // CSS
            // ============================================================
            tl.append("<style>");
            tl.append(".tl-wrap{font-family:Arial,sans-serif;padding:10px 0;position:relative;}");
            tl.append(".tl-line{position:relative;padding-left:30px;}");
            tl.append(".tl-line::before{content:'';position:absolute;left:10px;top:0;bottom:0;width:2px;background:#ddd;}");
            tl.append(".tl-node{position:relative;margin-bottom:8px;}");
            tl.append(".tl-node::before{content:'';position:absolute;left:-25px;top:15px;width:12px;height:12px;border-radius:50%;background:#006eb7;border:2px solid #fff;box-shadow:0 0 0 2px #006eb7;z-index:1;}");
