    "className": "org.joget.apps.form.model.Form",
    "properties": {
        "noPermissionMessage": "",
        "loadBinder": {
            "className": "org.joget.apps.form.lib.WorkflowFormBinder",
            "properties": {}
        },
        "name": "Split Portal Withdrawn List",
        "description": "Withdraw a Window Split request",
        "postProcessorRunOn": "both",
        "permission": {
            "className": "",
            "properties": {}
        },
        "id": "withdraw_split_portal",
        "postProcessor": {
            "className": "org.joget.apps.app.lib.BeanShellTool",
            "properties": {"script": "import org.joget.apps.app.service.AppUtil;
import org.joget.apps.app.service.AppService;
import org.joget.workflow.model.service.WorkflowManager;
import org.joget.workflow.util.WorkflowUtil;
import org.joget.commons.util.LogUtil;
import javax.servlet.http.HttpServletRequest;
import javax.sql.DataSource;
import java.net.URLDecoder;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

/*
 * SplitWithdraw v3 - Post Processing Tool of form "withdraw_split_portal"
 * (table app_fd_withdrawn_split). Open the form as  .../withdraw?process_id=<running process id>
 *
 * 1. Resolves the RUNNING split_portal process.
 * 2. Snapshots stage / pending-with / age / started (Joget deletes SHK rows after abort).
 * 3. Stamps the withdraw row (c_parent_id, c_status = Withdrawn, c_wd_*).
 * 4. Marks app_fd_portal_details_split as Withdrawn.
 * 5. Aborts the process.
 */

String TAG = "SplitWithdraw";
String VERSION = "SplitWithdraw v3";
LogUtil.info(TAG, VERSION + " STARTED");

WorkflowManager wm = (WorkflowManager) AppUtil.getApplicationContext().getBean("workflowManager");
AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
String actor = WorkflowUtil.getCurrentUsername();

// Joget passes the saved record's primary key to post processors as "recordId"
String formRowId = null;
try {
    if (recordId != void && recordId != null && !recordId.toString().trim().isEmpty()) {
        formRowId = recordId.toString().trim();
    }
} catch (Exception ignore) {
}

String processId = null;

// ============================================================
// 1. RESOLVE THE RUNNING PROCESS
// ============================================================
try {
    HttpServletRequest req = WorkflowUtil.getHttpServletRequest();
    java.util.List candidates = new java.util.ArrayList();
    if (req != null) {
        if (formRowId == null) {
            String postedId = req.getParameter("id");
            if (postedId != null && !postedId.trim().isEmpty() && !postedId.startsWith("#")) {
                formRowId = postedId.trim();
            }
        }
        candidates.add(req.getParameter("process_id"));
        candidates.add(req.getParameter("id"));
        candidates.add(formRowId);
        candidates.add(req.getParameter("_recordId"));

        String referer = req.getHeader("Referer");
        if (referer != null) {
            String[] keys = new String[] {"process_id=", "_recordId=", "&id=", "?id="};
            for (int k = 0; k < keys.length; k++) {
                int pos = referer.indexOf(keys[k]);
                if (pos >= 0) {
                    String v = referer.substring(pos + keys[k].length());
                    int amp = v.indexOf('&');
                    if (amp >= 0) v = v.substring(0, amp);
                    candidates.add(URLDecoder.decode(v, "UTF-8"));
                }
            }
        }
    }

    for (int i = 0; i < candidates.size() && processId == null; i++) {
        String c = (String) candidates.get(i);
        if (c == null) continue;
        c = c.trim();
        if (c.isEmpty() || c.startsWith("#")) continue;
        if (wm.getRunningProcessById(c) != null) {
            processId = c;
        }
    }
    LogUtil.info(TAG, "candidates=" + candidates + " formRowId=" + formRowId + " processId=" + processId);
} catch (Exception e) {
    LogUtil.error(TAG, e, "request read failed");
}

if (processId == null) {
    LogUtil.error(TAG, null, "no running process found - nothing withdrawn");
    return null;
}

String originId = processId;
try {
    String o = appService.getOriginProcessId(processId);
    if (o != null && !o.trim().isEmpty()) originId = o.trim();
} catch (Exception ignore) {
}

Connection con = null;
try {
    con = ds.getConnection();

    // ---- safety: only withdraw split_portal processes ----
    PreparedStatement chk = con.prepareStatement(
        "SELECT PDefName FROM SHKProcesses WHERE Id = ? AND PDefName LIKE 'split\\_portal#%'");
    chk.setString(1, processId);
    ResultSet crs = chk.executeQuery();
    boolean isSplit = crs.next();
    crs.close();
    chk.close();
    if (!isSplit) {
        LogUtil.error(TAG, null, processId + " is not a split_portal process - nothing withdrawn");
        return null;
    }

    // ============================================================
    // 2. FIND THE WITHDRAW ROW THIS SUBMISSION SAVED
    // ============================================================
    String rowId = null;
    PreparedStatement find = con.prepareStatement(
        "SELECT id FROM app_fd_withdrawn_split " +
        "WHERE id = ? OR id = ? OR id = ? " +
        "   OR ( createdBy = ? AND dateCreated >= NOW() - INTERVAL 2 MINUTE " +
        "        AND (c_parent_id IS NULL OR c_parent_id = '') ) " +
        "ORDER BY (id = ?) DESC, (id = ?) DESC, dateCreated DESC LIMIT 1");
    for (int attempt = 0; attempt < 6 && rowId == null; attempt++) {
        if (attempt > 0) Thread.sleep(500);
        String f = (formRowId == null) ? "" : formRowId;
        find.setString(1, f);
        find.setString(2, processId);
        find.setString(3, originId);
        find.setString(4, actor);
        find.setString(5, f);
        find.setString(6, processId);
        ResultSet fr = find.executeQuery();
        if (fr.next()) rowId = fr.getString(1);
        fr.close();
    }
    find.close();

    // ============================================================
    // 3. SNAPSHOT  (before the abort - Joget removes SHK rows afterwards)
    // ============================================================
    String stage = "";
    String activityDef = "";
    String pendingWith = "";
    String ageHrs = "";
    String startedAt = "";
    try {
        PreparedStatement snap = con.prepareStatement(
            "SELECT GROUP_CONCAT(DISTINCT act.Name ORDER BY act.Name SEPARATOR ', '), " +
            "       GROUP_CONCAT(DISTINCT act.ActivityDefinitionId ORDER BY act.ActivityDefinitionId SEPARATOR ', '), " +
            "       GROUP_CONCAT(DISTINCT ass.ResourceId ORDER BY ass.ResourceId SEPARATOR ', '), " +
            "       ROUND((UNIX_TIMESTAMP() * 1000 - MIN(act.Activated)) / 3600000, 1) " +
            "FROM SHKActivities act " +
            "JOIN SHKActivityStates st ON st.oid = act.State " +
            "JOIN SHKAssignmentsTable ass ON ass.ActivityId = act.Id AND ass.IsValid = 1 " +
            "WHERE act.ProcessId = ? AND st.KeyValue LIKE 'open.%'");
        snap.setString(1, processId);
        ResultSet srs = snap.executeQuery();
        if (srs.next()) {
            if (srs.getString(1) != null) stage = srs.getString(1);
            if (srs.getString(2) != null) activityDef = srs.getString(2);
            if (srs.getString(3) != null) pendingWith = srs.getString(3);
            if (srs.getString(4) != null) ageHrs = srs.getString(4);
        }
        srs.close();
        snap.close();

        PreparedStatement ps = con.prepareStatement(
            "SELECT DATE_FORMAT(FROM_UNIXTIME(Started / 1000), '%Y-%m-%d %H:%i:%s') FROM SHKProcesses WHERE Id = ?");
        ps.setString(1, processId);
        ResultSet prs = ps.executeQuery();
        if (prs.next() && prs.getString(1) != null) startedAt = prs.getString(1);
        prs.close();
        ps.close();
    } catch (Exception se) {
        LogUtil.error(TAG, se, "snapshot failed (continuing)");
    }
    LogUtil.info(TAG, "snapshot stage=[" + stage + "] pendingWith=[" + pendingWith + "] ageHrs=" + ageHrs + " started=" + startedAt);

    // ============================================================
    // 4. STAMP THE WITHDRAW ROW  (isolated: an error here never stops the abort)
    // ============================================================
    try {
        if (rowId != null) {
            PreparedStatement wu = con.prepareStatement(
                "UPDATE app_fd_withdrawn_split SET dateModified = NOW(), modifiedBy = ?, " +
                "c_parent_id = ?, c_status = 'Withdrawn', " +
                "c_wd_on = DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'), c_wd_by = ?, c_wd_started = ?, " +
                "c_wd_at_stage = ?, c_wd_at_activity_def = ?, c_wd_pending_with = ?, c_wd_age_hrs = ? " +
                "WHERE id = ?");
            wu.setString(1, actor);
            wu.setString(2, processId);
            wu.setString(3, actor);
            wu.setString(4, startedAt);
            wu.setString(5, stage);
            wu.setString(6, activityDef);
            wu.setString(7, pendingWith);
            wu.setString(8, ageHrs);
            wu.setString(9, rowId);
            LogUtil.info(TAG, "withdraw row " + rowId + " stamped=" + wu.executeUpdate());
            wu.close();
        } else {
            // no form row visible: keep an audit row so the request still appears in the list
            PreparedStatement wi = con.prepareStatement(
                "INSERT IGNORE INTO app_fd_withdrawn_split " +
                "(id, dateCreated, dateModified, createdBy, modifiedBy, c_parent_id, c_status, " +
                " c_wd_on, c_wd_by, c_wd_started, c_wd_at_stage, c_wd_at_activity_def, c_wd_pending_with, c_wd_age_hrs) " +
                "VALUES (?, NOW(), NOW(), ?, ?, ?, 'Withdrawn', DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s'), ?, ?, ?, ?, ?, ?)");
            wi.setString(1, processId);
            wi.setString(2, actor);
            wi.setString(3, actor);
            wi.setString(4, processId);
            wi.setString(5, actor);
            wi.setString(6, startedAt);
            wi.setString(7, stage);
            wi.setString(8, activityDef);
            wi.setString(9, pendingWith);
            wi.setString(10, ageHrs);
            LogUtil.warn(TAG, "withdraw form row not found - audit row inserted=" + wi.executeUpdate());
            wi.close();
        }
    } catch (Exception le) {
        LogUtil.error(TAG, le, "could not stamp withdraw row - check the c_wd_* columns exist. Continuing with abort.");
    }

    // ============================================================
    // 5. MAIN RECORD  (matched by id, origin id or c_parent_id)
    // ============================================================
    try {
        PreparedStatement up = con.prepareStatement(
            "UPDATE app_fd_portal_details_split SET dateModified = NOW(), modifiedBy = ?, " +
            "c_status = 'Withdrawn', c_stage_status = 'Withdrawn' " +
            "WHERE id = ? OR id = ? OR c_parent_id = ?");
        up.setString(1, actor);
        up.setString(2, processId);
        up.setString(3, originId);
        up.setString(4, processId);
        LogUtil.info(TAG, "main rows updated=" + up.executeUpdate());
        up.close();
    } catch (Exception me) {
        LogUtil.error(TAG, me, "could not mark main record Withdrawn - continuing with abort");
    }

    // ============================================================
    // 6. ABORT
    // ============================================================
    wm.processAbort(processId);
    LogUtil.info(TAG, actor + " aborted " + processId);

} catch (Exception e) {
    LogUtil.error(TAG, e, "withdrawal failed for processId=" + processId);
} finally {
    if (con != null) {
        try { con.close(); } catch (Exception ex) {}
    }
}

return null;"}
        },
        "storeBinder": {
            "className": "org.joget.apps.form.lib.WorkflowFormBinder",
            "properties": {}
        },
        "tableName": "withdrawn_split"
    }
}

