    "binder": {
        "className": "org.joget.apps.datalist.lib.BeanShellDatalistBinder",
        "properties": {
            "getDataScript": "import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.workflow.util.WorkflowUtil;
import org.joget.commons.util.LogUtil;
import java.util.*;
import org.joget.apps.datalist.model.DataListCollection;

String DATALIST_ID   = "d-6052549";
String USERVIEW_BASE = "/jw/web/userview/split_portal/split_portal/_/";
String DETAILS_MENU  = "view_details";
int GREEN_MAX_DAYS   = 15;
int YELLOW_MAX_DAYS  = 30;
int ORANGE_MAX_DAYS  = 45;

public String esc(String v) {
    if (v == null) return "";
    return v.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&#39;");
}

public String pill(String bg, String fg, String text) {
    return "<span style='background:" + bg + "; color:" + fg + "; padding:3px 10px; border-radius:12px; font-weight:bold; font-size:12px; white-space:nowrap;'>" + text + "</span>";
}

public String duration(long mins) {
    if (mins < 0) return "-";
    long d = mins / 1440;
    long h = (mins % 1440) / 60;
    long m = mins % 60;
    return (d > 0 ? d + "d " : "") + (h > 0 ? h + "h " : "") + m + "m";
}

DataListCollection data = new DataListCollection();
Connection con = null;

String search = WorkflowUtil.getHttpServletRequest().getParameter(DATALIST_ID + "-fn_erp_name");
if (search == null) search = "";
search = search.trim();

try {
    DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
    con = ds.getConnection();

    String sql =
        "SELECT v.process_id, " +
        "COALESCE(NULLIF(v.c_erp_legal_name,''), NULLIF(v.c_new_portal_erp_legal_name,''), NULLIF(v.c_existing_window_name,''), '-') AS erp_name, " +
        "v.c_existing_window_name, v.c_new_erp_portal_name, v.c_zone, " +
        "COALESCE(v.process_initiator_name, v.process_initiator) AS initiated_by, " +
        "COALESCE(v.process_started_at, v.created_date) AS started_at, " +
        "v.sales_done_at AS completed_at, " +
        "TIMESTAMPDIFF(MINUTE, COALESCE(v.process_started_at, v.created_date), v.sales_done_at) AS total_minutes, " +
        "v.c_budget_approval, v.c_user_shifted_to_new_portal " +
        "FROM vw_split_portal_master v " +
        "WHERE v.sales_done_at IS NOT NULL AND v.current_pending_steps IS NULL ";
    if (!search.isEmpty()) {
        sql += "AND (v.c_erp_legal_name LIKE ? OR v.c_new_portal_erp_legal_name LIKE ? OR v.c_existing_window_name LIKE ? OR v.c_new_erp_portal_name LIKE ? OR v.c_zone LIKE ?) ";
    }
    sql += "ORDER BY v.sales_done_at DESC";

    PreparedStatement stmt = con.prepareStatement(sql);
    if (!search.isEmpty()) {
        for (int i = 1; i <= 5; i++) stmt.setString(i, "%" + search + "%");
    }

    ResultSet rs = stmt.executeQuery();
    while (rs.next()) {
        Map row = new HashMap();
        String processId = rs.getString("process_id");

        row.put("id", processId);
        row.put("process_id", processId);
        row.put("erp_name", "<b>" + esc(rs.getString("erp_name")) + "</b>");
        row.put("existing_window_name", esc(rs.getString("c_existing_window_name")));
        row.put("new_erp_portal_name", esc(rs.getString("c_new_erp_portal_name")));
        row.put("zone", esc(rs.getString("c_zone")));
        row.put("initiated_by", esc(rs.getString("initiated_by")));
        row.put("process_started_at", esc(rs.getString("started_at")));
        row.put("process_completed_at", esc(rs.getString("completed_at")));

        long totalMinutes = rs.getLong("total_minutes");
        if (rs.wasNull()) totalMinutes = -1;
        long days = totalMinutes / 1440;
        String color = "#28a745";
        if (days > ORANGE_MAX_DAYS)      color = "#dc3545";
        else if (days > YELLOW_MAX_DAYS) color = "#fd7e14";
        else if (days > GREEN_MAX_DAYS)  color = "#ffc107";
        row.put("completed_in", "<span style='font-weight:bold; color:" + color + "; white-space:nowrap;'>⏱️ " + duration(totalMinutes) + "</span>");

        String approval = rs.getString("c_budget_approval");
        if (approval == null || approval.trim().isEmpty()) {
            row.put("approval_status", pill("#e9ecef", "#6c757d", "—"));
        } else if (approval.equalsIgnoreCase("yes") || approval.equalsIgnoreCase("approve") || approval.equalsIgnoreCase("approved")) {
            row.put("approval_status", pill("#d4edda", "#155724", "✅ APPROVED"));
        } else {
            row.put("approval_status", pill("#f8d7da", "#721c24", "❌ " + esc(approval.toUpperCase())));
        }

        String shifted = rs.getString("c_user_shifted_to_new_portal");
        if (shifted == null || shifted.trim().isEmpty()) {
            row.put("shift_status", pill("#e9ecef", "#6c757d", "—"));
        } else if (shifted.equalsIgnoreCase("yes")) {
            row.put("shift_status", pill("#d4edda", "#155724", "✅ SHIFTED"));
        } else {
            row.put("shift_status", pill("#f8d7da", "#721c24", "⚠️ NOT SHIFTED"));
        }

        row.put("view_details",
            "<a href='" + USERVIEW_BASE + DETAILS_MENU + "?_recordId=" + processId + "' target='_blank' " +
            "style='background:#1a1a2e; color:#fff; padding:5px 12px; border-radius:5px; font-size:12px; font-weight:600; text-decoration:none; display:inline-block; white-space:nowrap;'>" +
            "📋 View Details</a>");

        data.add(row);
    }
    rs.close();
    stmt.close();
} catch (Exception e) {
    LogUtil.error("SPLIT_Completed", e, e.getMessage());
} finally {
    if (con != null) try { con.close(); } catch (Exception ex) {}
}

return data;",
