import org.joget.apps.app.service.AppUtil;
import org.joget.workflow.util.WorkflowUtil;
import org.joget.commons.util.LogUtil;

int count = 0;
Connection con = null;

String DATALIST_ID = "d-1340104";

String currentUser = WorkflowUtil.getCurrentUsername();
String search = WorkflowUtil.getHttpServletRequest().getParameter(DATALIST_ID + "-fn_erp_legal_name");
if (search == null) search = "";
search = search.trim();

try {
    DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
    con = ds.getConnection();

    String sql = "SELECT COUNT(*) AS total FROM vw_split_in_progress WHERE pending_user = ? ";
    if (!search.isEmpty()) {
        sql += "AND (erp_legal_name LIKE ? OR existing_window_name LIKE ? OR new_erp_portal_name LIKE ? OR zone LIKE ? OR active_stage LIKE ?) ";
    }

    PreparedStatement stmt = con.prepareStatement(sql);
    stmt.setString(1, currentUser);
    if (!search.isEmpty()) {
        for (int i = 2; i <= 6; i++) stmt.setString(i, "%" + search + "%");
    }

    ResultSet rs = stmt.executeQuery();
    if (rs.next()) count = rs.getInt("total");
    rs.close();
    stmt.close();
} catch (Exception e) {
    LogUtil.error("SPLIT_MyTasks_Count", e, e.getMessage());
} finally {
    if (con != null) try { con.close(); } catch (Exception ex) {}
}

return count;",
