            "getDataScript": "import java.sql.*;
import javax.sql.DataSource;
import java.util.*;
import java.net.URLEncoder;
import javax.servlet.http.HttpServletRequest;
import org.joget.apps.app.service.AppUtil;
import org.joget.apps.app.model.AppDefinition;
import org.joget.workflow.util.WorkflowUtil;
import org.joget.commons.util.LogUtil;
import org.joget.apps.datalist.model.DataListCollection;

// ======================= CONFIG ==========================================
String USERVIEW_ID   = "split_portal";          // fallback only (normally read from the page URL)
String DETAILS_MENU  = "view_details";          // menu id of the details page
String PROOF_FORM_ID = "withdraw_split_portal"; // FORM id of the withdraw form
// =========================================================================

String TAG = "SPLIT_Withdrawn";
DataListCollection data = new DataListCollection();

String esc(String v) {
    if (v == null) return "";
    return v.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace("\"", "&quot;").replace("'", "&#39;");
}
String dash(String v) {
    return (v == null || v.trim().isEmpty()) ? "<span style='color:#aaa;'>&mdash;</span>" : esc(v);
}
String enc(String v) {
    return URLEncoder.encode(v == null ? "" : v, "UTF-8").replace("+", "%20");
}

HttpServletRequest req = WorkflowUtil.getHttpServletRequest();
String ctx = (req != null) ? req.getContextPath() : "/jw";

String APP_ID = "split_portal";
String APP_VERSION = "1";
try {
    AppDefinition ad = AppUtil.getCurrentAppDefinition();
    if (ad != null) {
        APP_ID = ad.getAppId();
        APP_VERSION = ad.getVersion().toString();
    }
} catch (Exception ignore) {}

String uvBase = null;
try {
    String uri = req.getRequestURI();
    int p = uri.indexOf("/_/");
    if (p > 0) uvBase = uri.substring(0, p + 3);
} catch (Exception ignore) {}
if (uvBase == null) uvBase = ctx + "/web/userview/" + APP_ID + "/" + USERVIEW_ID + "/_/";

// search: any datalist filter named "...-fn_erp_name" (no datalist id needed)
String search = "";
try {
    Enumeration en = req.getParameterNames();
    while (en.hasMoreElements()) {
        String n = (String) en.nextElement();
        if (n.endsWith("-fn_erp_name")) {
            String v = req.getParameter(n);
            if (v != null && !v.trim().isEmpty()) { search = v.trim(); break; }
        }
    }
} catch (Exception ignore) {}

Map SORTABLE = new HashMap();
SORTABLE.put("erp_name",             "erp_name");
SORTABLE.put("existing_window_name", "existing_window_name");
SORTABLE.put("new_erp_portal_name",  "new_erp_portal_name");
SORTABLE.put("zone",                 "zone");
SORTABLE.put("raised_by",            "raised_by");
SORTABLE.put("started",              "started");
SORTABLE.put("killed_at_stage",      "killed_at_stage");
SORTABLE.put("age_at_kill",          "pending_hrs_at_kill");
SORTABLE.put("withdrawn_by",         "withdrawn_by");
SORTABLE.put("withdrawn_on",         "withdrawn_on");
SORTABLE.put("reason",               "reason");
SORTABLE.put("approval_proof",       "proof_file");

String  sortCol  = null;
boolean sortDesc = false;
int     startRow = 0;
int     pageSize = 0;
if (sort  != void && sort  != null && !sort.toString().trim().isEmpty()) sortCol = (String) SORTABLE.get(sort.toString());
if (desc  != void && desc  != null) sortDesc = desc.booleanValue();
if (start != void && start != null) startRow = start.intValue();
if (rows  != void && rows  != null) pageSize = rows.intValue();

Connection con = null;
PreparedStatement stmt = null;
ResultSet rs = null;

try {
    DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
    con = ds.getConnection();

    String sql = "SELECT * FROM vw_split_withdrawn ";
    if (!search.isEmpty()) {
        sql += "WHERE (erp_name LIKE ? OR existing_window_name LIKE ? OR new_erp_portal_name LIKE ? " +
               "OR zone LIKE ? OR killed_at_stage LIKE ? OR process_id LIKE ?) ";
    }
    sql += (sortCol != null)
        ? "ORDER BY " + sortCol + (sortDesc ? " DESC" : " ASC") + ", process_id "
        : "ORDER BY withdrawn_on DESC, process_id ";
    if (pageSize > 0) sql += "LIMIT " + pageSize + " OFFSET " + startRow;

    stmt = con.prepareStatement(sql);
    if (!search.isEmpty()) {
        for (int i = 1; i <= 6; i++) stmt.setString(i, "%" + search + "%");
    }
    rs = stmt.executeQuery();

    while (rs.next()) {
        Map row = new HashMap();
        String processId = rs.getString("process_id");
        String recordIdV = rs.getString("record_id");

        row.put("id", processId);
        row.put("process_id", esc(processId));

        String erp = rs.getString("erp_name");
        if (erp == null || erp.trim().isEmpty() || erp.equals("(not submitted)")) {
            row.put("erp_name", "<i style='color:#888;'>(not submitted)</i>");
        } else {
            row.put("erp_name", "<b>" + esc(erp) + "</b>");
        }

        row.put("existing_window_name", dash(rs.getString("existing_window_name")));
        row.put("new_erp_portal_name",  dash(rs.getString("new_erp_portal_name")));
        row.put("zone",                 dash(rs.getString("zone")));
        row.put("raised_by",            dash(rs.getString("raised_by")));
        row.put("started",              "<span style='white-space:nowrap;'>" + dash(rs.getString("started")) + "</span>");

        // ---- killed at stage (one pill per stage, no for-each loop) ----
        String stage = rs.getString("killed_at_stage");
        if (stage == null || stage.trim().isEmpty()) {
            row.put("killed_at_stage", "<span style='color:#aaa;'>&mdash;</span>");
        } else {
            String[] parts = stage.split(", ");
            StringBuilder pills = new StringBuilder();
            for (int i = 0; i < parts.length; i++) {
                pills.append("<span style='background:#fde8e8; color:#dc3545; padding:3px 8px; border-radius:12px; " +
                             "font-weight:bold; font-size:11px; display:inline-block; margin:1px 0;'>")
                     .append(esc(parts[i])).append("</span><br>");
            }
            row.put("killed_at_stage", pills.toString());
        }

        // ---- age at kill ----
        double ageHrs = rs.getDouble("pending_hrs_at_kill");
        if (rs.wasNull()) {
            row.put("age_at_kill", "<span style='color:#aaa;'>&mdash;</span>");
        } else {
            long totalMins = Math.round(ageHrs * 60);
            long d = totalMins / 1440;
            long h = (totalMins % 1440) / 60;
            long m = totalMins % 60;
            String ageTxt = (d > 0 ? d + "d " : "") + (h > 0 ? h + "h " : "") + (d == 0 ? m + "m" : "");
            String ageColor = "#28a745";
            if (ageHrs > 24)     ageColor = "#dc3545";
            else if (ageHrs > 8) ageColor = "#fd7e14";
            row.put("age_at_kill", "<span style='font-weight:bold; color:" + ageColor + "; white-space:nowrap;'>" + ageTxt.trim() + "</span>");
        }

        // ---- withdrawn by / on ----
        String by = rs.getString("withdrawn_by");
        row.put("withdrawn_by", (by == null || by.trim().isEmpty())
            ? "<i style='color:#888;'>Aborted (no withdraw form)</i>"
            : "<b>" + esc(by) + "</b>");
        row.put("withdrawn_on", "<span style='white-space:nowrap;'>" + dash(rs.getString("withdrawn_on")) + "</span>");

        // ---- reason ----
        String reason = rs.getString("reason");
        if (reason == null || reason.trim().isEmpty()) {
            row.put("reason", "<span style='color:#aaa;'>&mdash;</span>");
        } else {
            String shortReason = reason.length() > 60 ? reason.substring(0, 60) + "..." : reason;
            row.put("reason", "<span title=\"" + esc(reason) + "\">" + esc(shortReason) + "</span>");
        }

        // ---- proof download (file lives under the withdraw row's own id) ----
        String proof = rs.getString("proof_file");
        String proofRowId = rs.getString("proof_row_id");
        if (proof != null && !proof.trim().isEmpty() && proofRowId != null) {
            String firstFile = proof.split(";")[0].trim();
            String url = ctx + "/web/client/app/" + APP_ID + "/" + APP_VERSION + "/form/download/" +
                         PROOF_FORM_ID + "/" + enc(proofRowId) + "/" + enc(firstFile) + ".?attachment=true";
            row.put("approval_proof",
                "<a href=\"" + url + "\" target=\"_blank\" title=\"" + esc(firstFile) + "\" " +
                "style=\"background:#1a1a2e; color:#fff; padding:5px 12px; border-radius:5px; font-size:12px; " +
                "font-weight:600; text-decoration:none; display:inline-block; white-space:nowrap;\">&#128206; Download</a>");
        } else {
            row.put("approval_proof", "<span style=\"color:#dc3545; font-size:12px;\">&#9888; No proof</span>");
        }

        // ---- details link uses the ERP RECORD id (may differ from process id) ----
        String detailsId = (recordIdV == null || recordIdV.isEmpty()) ? processId : recordIdV;
        row.put("view_details",
            "<a href=\"" + uvBase + DETAILS_MENU + "?_recordId=" + enc(detailsId) + "\" target=\"_blank\" " +
            "style=\"background:#1a1a2e; color:#fff; padding:5px 12px; border-radius:5px; font-size:12px; " +
            "font-weight:600; text-decoration:none; display:inline-block; white-space:nowrap;\">&#128203; View Details</a>");

        data.add(row);
    }
} catch (Exception e) {
    LogUtil.error(TAG, e, "rows failed: " + e.getMessage());
} finally {
    if (rs != null)   try { rs.close(); }   catch (Exception ex) {}
    if (stmt != null) try { stmt.close(); } catch (Exception ex) {}
    if (con != null)  try { con.close(); }  catch (Exception ex) {}
}

return data;",
            "getTotalScript": "import java.sql.*;
import javax.sql.DataSource;
import java.util.*;
import javax.servlet.http.HttpServletRequest;
import org.joget.apps.app.service.AppUtil;
import org.joget.workflow.util.WorkflowUtil;
import org.joget.commons.util.LogUtil;

int count = 0;

// search: any datalist filter named "...-fn_erp_name" (same rule as the rows script)
String search = "";
try {
    HttpServletRequest req = WorkflowUtil.getHttpServletRequest();
    Enumeration en = req.getParameterNames();
    while (en.hasMoreElements()) {
        String n = (String) en.nextElement();
        if (n.endsWith("-fn_erp_name")) {
            String v = req.getParameter(n);
            if (v != null && !v.trim().isEmpty()) { search = v.trim(); break; }
        }
    }
} catch (Exception ignore) {}

Connection con = null;
PreparedStatement stmt = null;
ResultSet rs = null;
try {
    DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
    con = ds.getConnection();

    String sql = "SELECT COUNT(*) AS total FROM vw_split_withdrawn ";
    if (!search.isEmpty()) {
        sql += "WHERE (erp_name LIKE ? OR existing_window_name LIKE ? OR new_erp_portal_name LIKE ? " +
               "OR zone LIKE ? OR killed_at_stage LIKE ? OR process_id LIKE ?) ";
    }
    stmt = con.prepareStatement(sql);
    if (!search.isEmpty()) {
        for (int i = 1; i <= 6; i++) stmt.setString(i, "%" + search + "%");
    }
    rs = stmt.executeQuery();
    if (rs.next()) count = rs.getInt("total");
} catch (Exception e) {
    LogUtil.error("SPLIT_Withdrawn_Count", e, "count failed: " + e.getMessage());
} finally {
    if (rs != null)   try { rs.close(); }   catch (Exception ex) {}
    if (stmt != null) try { stmt.close(); } catch (Exception ex) {}
    if (con != null)  try { con.close(); }  catch (Exception ex) {}
}
return count;",
            "getColumnScript": "import org.joget.apps.datalist.model.DataListColumn;

DataListColumn[] columns = new DataListColumn[14];
columns[0]  = new DataListColumn("process_id",           "Process ID",        false);
columns[1]  = new DataListColumn("erp_name",             "ERP Legal Name",    true);
columns[2]  = new DataListColumn("existing_window_name", "Existing Window",   true);
columns[3]  = new DataListColumn("new_erp_portal_name",  "New Portal Name",   true);
columns[4]  = new DataListColumn("zone",                 "Zone",              true);
columns[5]  = new DataListColumn("raised_by",            "Raised By",         true);
columns[6]  = new DataListColumn("started",              "Started",           true);
columns[7]  = new DataListColumn("killed_at_stage",      "Killed At Stage",   true);
columns[8]  = new DataListColumn("age_at_kill",          "Age At Kill",       true);
columns[9]  = new DataListColumn("withdrawn_by",         "Withdrawn By",      true);
columns[10] = new DataListColumn("withdrawn_on",         "Withdrawn On",      true);
columns[11] = new DataListColumn("reason",               "Reason",            true);
columns[12] = new DataListColumn("approval_proof",       "Proof",             true);
